import clsx from "clsx";
import { useCallback, useEffect, useState } from "react";
import { Download, RefreshCw } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { DisableMCP, EnableMCP, MCPAudit, MCPStatus } from "../../wailsjs/go/controllers/MCP";
// @ts-ignore wailsjs bindings are generated by wails build
import { ApplyUpdate, CheckUpdates, DownloadUpdate, WebViewRuntimeState } from "../../wailsjs/go/controllers/Updates";
// @ts-ignore wailsjs bindings are generated by wails build
import { GetTheme, SetTheme } from "../../wailsjs/go/controllers/System";
// @ts-ignore wailsjs bindings are generated by wails build
import { GetTuning, LocalCAStatus, SetTuning, TrustLocalCA } from "../../wailsjs/go/controllers/Projects";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useI18n, useT } from "../lib/i18n";
import { applyTheme, getCurrentTheme, THEMES, type ThemeId } from "../theme";

// Settings: appearance and language (Phase 0), the experimental MCP
// surface and the updater (Phase 6).
export default function Settings() {
  const t = useT();
  return (
    <div className="mx-auto max-w-[860px] space-y-4">
      <h1 className="text-lg font-semibold text-white/95">{t("settings.title")}</h1>
      <AppearanceSection />
      <LanguageSection />
      <ExperimentalSection />
      <UpdatesSection />
      <TuningSection />
      <DiagnosticsSection />
    </div>
  );
}

function Panel({ title, help, children }: { title: string; help?: string; children: React.ReactNode }) {
  return (
    <section className="glass p-4">
      <h2 className="text-sm font-semibold text-white/90">{title}</h2>
      {help && <p className="mt-1 text-xs leading-relaxed text-white/55">{help}</p>}
      <div className="mt-3">{children}</div>
    </section>
  );
}

function AppearanceSection() {
  const t = useT();
  const [theme, setTheme] = useState<ThemeId>(() => getCurrentTheme());

  // The config file is the source of truth across processes; localStorage
  // stays as the pre-hydration fallback.
  useEffect(() => {
    const timer = setTimeout(() => {
      GetTheme()
        .then((id: string) => {
          if (id) {
            applyTheme(id as ThemeId);
            setTheme(id as ThemeId);
          }
        })
        .catch(() => {});
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const pick = (id: ThemeId) => {
    applyTheme(id);
    setTheme(id);
    SetTheme(id).catch(() => {
      /* config unavailable: localStorage still holds the choice */
    });
  };

  return (
    <Panel title={t("settings.appearance.title")} help={t("settings.appearance.themesHelp")}>
      <div className="mb-2 text-xs font-medium text-white/70">{t("settings.appearance.themesLabel")}</div>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        {THEMES.map((def) => (
          <button
            key={def.id}
            type="button"
            onClick={() => pick(def.id)}
            aria-pressed={theme === def.id}
            className={clsx(
              "flex items-center gap-3 rounded-lg border p-2.5 text-left transition-colors",
              theme === def.id
                ? "border-accent bg-accent/15"
                : "border-white/10 bg-white/[0.03] hover:bg-white/[0.06]",
            )}
          >
            <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md border border-white/15">
              <span className="h-2 w-2 rounded-full" style={{ background: def.swatch[0] }} />
              <span className="ml-1 h-2 w-2 rounded-full" style={{ background: def.swatch[1] }} />
            </span>
            <span className="min-w-0">
              <span className="block truncate text-[13px] font-medium text-white/90">{def.label}</span>
              <span className="block truncate text-[11px] text-white/50">{t(def.descriptionKey)}</span>
            </span>
          </button>
        ))}
      </div>
    </Panel>
  );
}

function LanguageSection() {
  const t = useT();
  const { lang, locales, setLang } = useI18n();

  return (
    <Panel title={t("settings.language.title")} help={t("settings.language.help")}>
      <select
        className="input max-w-[320px]"
        value={lang}
        onChange={(event) => setLang(event.target.value)}
        aria-label={t("settings.language.title")}
      >
        {locales.map((meta) => (
          <option key={meta.code} value={meta.code}>
            {meta.nativeName} ({meta.name}){meta.autoTranslated ? " · " + t("settings.language.needsReview") : ""}
          </option>
        ))}
      </select>
    </Panel>
  );
}


type MCPStatusView = {
  enabled: boolean;
  url?: string;
  clients?: { client: string; label: string; registered: boolean }[];
};

type AuditEntry = { time: string; method: string; ok: boolean; errorHint?: string; source: string };

function ExperimentalSection() {
  const t = useT();
  const dialogs = useDialogs();
  const [status, setStatus] = useState<MCPStatusView | null>(null);
  const [audit, setAudit] = useState<AuditEntry[]>([]);
  const [busy, setBusy] = useState(false);

  const refresh = useCallback(() => {
    MCPStatus()
      .then((s: MCPStatusView) => setStatus(s))
      .catch(() => setStatus(null));
    MCPAudit(20)
      .then((list: AuditEntry[]) => setAudit(list ?? []))
      .catch(() => setAudit([]));
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const toggle = async () => {
    setBusy(true);
    try {
      if (status?.enabled) {
        await DisableMCP();
      } else {
        await EnableMCP();
      }
      refresh();
    } catch (error) {
      await dialogs.alert({ title: "MCP", message: String(error) });
    } finally {
      setBusy(false);
    }
  };

  return (
    <Panel title={t("settings.mcp.title")} help={t("settings.mcp.help")}>
      <div className="flex items-center gap-3">
        <button
          type="button"
          disabled={busy}
          onClick={() => void toggle()}
          className={`rounded-md border px-3 py-1.5 text-xs font-medium ${
            status?.enabled
              ? "border-emerald-400/40 bg-emerald-500/10 text-emerald-300 hover:bg-emerald-500/20"
              : "border-white/15 bg-white/5 text-white/70 hover:bg-white/10"
          } disabled:opacity-40`}
        >
          {status?.enabled ? t("settings.mcp.on") : t("settings.mcp.off")}
        </button>
        {status?.url && <span className="font-mono text-[10px] text-white/40">{status.url}</span>}
      </div>
      {status?.clients && status.clients.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-1.5">
          {status.clients.map((client) => (
            <span
              key={client.client}
              title={
                client.registered
                  ? t("settings.mcp.registered")
                  : t("settings.mcp.notRegistered")
              }
              className={`rounded-full border px-2 py-0.5 text-[10px] ${
                client.registered
                  ? "border-emerald-400/40 text-emerald-300"
                  : "border-white/10 text-white/30"
              }`}
            >
              {client.label}
            </span>
          ))}
        </div>
      )}
      {audit.length > 0 && (
        <details className="mt-3 rounded border border-white/10">
          <summary className="cursor-pointer px-2 py-1 text-[10px] text-white/40 hover:text-white/70">
            {t("settings.mcp.audit")}
          </summary>
          <div className="max-h-40 space-y-0.5 overflow-y-auto px-2 py-1">
            {audit.map((entry, i) => (
              <div key={i} className="flex items-baseline gap-2 font-mono text-[9px]">
                <span className="shrink-0 text-white/25">
                  {new Date(entry.time).toLocaleTimeString()}
                </span>
                <span className={entry.ok ? "text-white/60" : "text-red-300"}>{entry.method}</span>
                {!entry.ok && entry.errorHint && (
                  <span className="min-w-0 flex-1 truncate text-red-300/60">{entry.errorHint}</span>
                )}
              </div>
            ))}
          </div>
        </details>
      )}
    </Panel>
  );
}

type UpdateCheckView = {
  current: string;
  latest: string;
  newer: boolean;
  releaseUrl?: string;
  assetName?: string;
  error?: string;
};

function UpdatesSection() {
  const t = useT();
  const dialogs = useDialogs();
  const [check, setCheck] = useState<UpdateCheckView | null>(null);
  const [staged, setStaged] = useState("");
  const [busy, setBusy] = useState(false);

  const runCheck = async () => {
    setBusy(true);
    try {
      setCheck(await CheckUpdates());
    } finally {
      setBusy(false);
    }
  };

  const download = async () => {
    setBusy(true);
    try {
      setStaged(await DownloadUpdate());
    } catch (error) {
      await dialogs.alert({ title: t("settings.updates.title"), message: String(error) });
    } finally {
      setBusy(false);
    }
  };

  const apply = async () => {
    try {
      const result = await ApplyUpdate();
      await dialogs.alert({
        title: t("settings.updates.title"),
        message: result?.portable
          ? t("settings.updates.portableHint")
          : t("settings.updates.msiHint"),
      });
    } catch (error) {
      await dialogs.alert({ title: t("settings.updates.title"), message: String(error) });
    }
  };

  return (
    <Panel title={t("settings.updates.title")} help={t("settings.updates.help")}>
      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          disabled={busy}
          onClick={() => void runCheck()}
          className="flex items-center gap-1.5 rounded-md border border-white/15 bg-white/5 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10 disabled:opacity-40"
        >
          <RefreshCw className={`h-3 w-3 ${busy ? "animate-spin" : ""}`} />{" "}
          {t("settings.updates.check")}
        </button>
        {check && !check.error && (
          <span className="text-xs text-white/60">
            {check.current} → {check.latest}
            {check.newer && (
              <span className="ml-2 rounded-full border border-amber-400/40 px-2 py-0.5 text-[10px] text-amber-300">
                {t("settings.updates.available")}
              </span>
            )}
          </span>
        )}
        {check?.error && <span className="text-xs text-white/40">{check.error}</span>}
        {check?.newer && !staged && (
          <button
            type="button"
            disabled={busy}
            onClick={() => void download()}
            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85 disabled:opacity-40"
          >
            <Download className="h-3 w-3" /> {t("settings.updates.download")}
          </button>
        )}
        {staged && (
          <button
            type="button"
            onClick={() => void apply()}
            className="rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
          >
            {t("settings.updates.apply")}
          </button>
        )}
      </div>
    </Panel>
  );
}


type CAStatus = { exists: boolean; commonName?: string; thumbprint?: string; trusted: boolean };
type WebViewState = { installed: boolean; version: string; perUser: boolean; recoverable: boolean; hint?: string };

function DiagnosticsSection() {
  const t = useT();
  const dialogs = useDialogs();
  const [ca, setCa] = useState<CAStatus | null>(null);
  const [web, setWeb] = useState<WebViewState | null>(null);
  const [trusting, setTrusting] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      LocalCAStatus()
        .then((s) => setCa(s as CAStatus))
        .catch(() => setCa(null));
      WebViewRuntimeState()
        .then((s: WebViewState) => setWeb(s))
        .catch(() => setWeb(null));
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const trust = async () => {
    setTrusting(true);
    try {
      await TrustLocalCA();
      const s = await LocalCAStatus();
      setCa(s as CAStatus);
    } catch (error) {
      await dialogs.alert({ title: t("settings.ca.title"), message: String(error) });
    } finally {
      setTrusting(false);
    }
  };

  return (
    <Panel title={t("settings.diagnostics.title")} help={t("settings.diagnostics.help")}>
      {/* Local CA card */}
      <div className="flex items-center gap-3">
        <div className="min-w-0 flex-1">
          <p className="text-xs font-medium text-white/80">{t("settings.ca.title")}</p>
          <p className="mt-0.5 text-[11px] text-white/45">
            {ca?.trusted ? t("settings.ca.trusted") : t("settings.ca.untrusted")}
            {ca?.commonName ? " · " + ca.commonName : ""}
          </p>
        </div>
        {ca && !ca.trusted && (
          <button
            type="button"
            disabled={trusting}
            onClick={() => void trust()}
            className="shrink-0 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85 disabled:opacity-40"
          >
            {trusting ? t("settings.ca.trusting") : t("settings.ca.trust")}
          </button>
        )}
      </div>
      {/* WebView2 runtime card */}
      {web && (
        <div className="mt-3 border-t border-white/5 pt-3">
          <p className="text-xs font-medium text-white/80">WebView2</p>
          <p className="mt-0.5 text-[11px] text-white/45">
            {web.installed
              ? `${t("settings.webview.installed")} · ${web.version}${web.perUser ? " · per-user" : ""}`
              : t("settings.webview.missing")}
          </p>
          {!web.installed && web.hint && <p className="mt-1 text-[11px] text-amber-300/80">{web.hint}</p>}
        </div>
      )}
    </Panel>
  );
}


type TuningCard = { server: string; values?: Record<string, string>; available?: string[] };

function TuningSection() {
  const t = useT();
  const dialogs = useDialogs();
  const [cards, setCards] = useState<TuningCard[]>([]);
  const [drafts, setDrafts] = useState<Record<string, Record<string, string>>>({});
  const [busy, setBusy] = useState("");

  const load = useCallback(() => {
    GetTuning()
      .then((list) => {
        setCards(list ?? []);
        const next: Record<string, Record<string, string>> = {};
        for (const card of list ?? []) {
          next[card.server] = { ...(card.values ?? {}) };
        }
        setDrafts(next);
      })
      .catch(() => setCards([]));
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => load(), 0);
    return () => clearTimeout(timer);
  }, [load]);

  const save = async (server: string, directive: string) => {
    const value = (drafts[server] ?? {})[directive] ?? "";
    if (value === ((cards.find((c) => c.server === server)?.values ?? {})[directive] ?? "")) {
      return; // unchanged
    }
    setBusy(server + directive);
    try {
      await SetTuning(server, directive, value);
      load();
    } catch (error) {
      await dialogs.alert({ title: server, message: String(error) });
    } finally {
      setBusy("");
    }
  };

  return (
    <Panel title={t("settings.tuning.title")} help={t("settings.tuning.help")}>
      {cards.length === 0 ? (
        <p className="text-xs text-white/40">{t("settings.tuning.empty")}</p>
      ) : (
        cards.map((card) => (
          <div key={card.server} className="mb-3 last:mb-0 border-t border-white/5 pt-3 first:border-t-0 first:pt-0">
            <p className="mb-2 text-xs font-medium text-white/80">
              {card.server === "nginx" ? "nginx" : "PHP " + card.server.replace("php-", "")}
            </p>
            <div className="grid grid-cols-2 gap-2">
              {(card.available ?? []).map((directive) => (
                <label key={directive} className="flex items-center gap-2 text-[11px]">
                  <span className="w-44 shrink-0 truncate font-mono text-white/55" title={directive}>
                    {directive}
                  </span>
                  <input
                    className="input min-w-0 flex-1 py-1 font-mono text-[11px]"
                    value={(drafts[card.server] ?? {})[directive] ?? ""}
                    placeholder={t("settings.tuning.default")}
                    onChange={(e) =>
                      setDrafts((prev) => ({
                        ...prev,
                        [card.server]: { ...(prev[card.server] ?? {}), [directive]: e.target.value },
                      }))
                    }
                    onKeyDown={(e) => {
                      if (e.key === "Enter") void save(card.server, directive);
                    }}
                  />
                  <button
                    type="button"
                    disabled={busy === card.server + directive}
                    onClick={() => void save(card.server, directive)}
                    className="shrink-0 rounded bg-accent px-2 py-1 text-[10px] font-medium text-white disabled:opacity-40"
                  >
                    {t("settings.tuning.save")}
                  </button>
                </label>
              ))}
            </div>
          </div>
        ))
      )}
    </Panel>
  );
}
